import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.DlQ8ZhpE.js";const u=JSON.parse('{"title":"Traffic and Request Rate Limiting","description":"","frontmatter":{"title":"Traffic and Request Rate Limiting","order":2},"headers":[],"relativePath":"docs/features/rate-limiting.md","filePath":"en/docs/features/rate-limiting.md"}'),n={name:"docs/features/rate-limiting.md"};function r(l,e,o,c,p,d){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="traffic-and-request-rate-limiting" tabindex="-1">Traffic and Request Rate Limiting <a class="header-anchor" href="#traffic-and-request-rate-limiting" aria-label="Permalink to &quot;Traffic and Request Rate Limiting&quot;">​</a></h1><p>Pavonis supports two types of rate limiting: traffic limiting (bandwidth control) and request rate limiting (QPS control). All limits are optional. See <a href="./../config/resource-limit"><code>ResourceLimitConfig</code></a> for the fields and configuration examples.</p><p>Limits apply at two levels:</p><ul><li>Per client: traffic and request rate limits are tracked separately for each client, and each client has its own quota</li><li>Global: traffic can additionally be capped for all clients combined</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>request ──► client request rate (s/min/h) ── exceeded ──► 429</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ▼ allowed</span></span>
<span class="line"><span>data ─────► client traffic bucket ──► global traffic bucket ──► transfer</span></span>
<span class="line"><span>            (waits when short of tokens: slows down, never rejects)</span></span></code></pre></div><p>A request must satisfy all configured limits. The limits apply to all proxy sites except <a href="./../sites/speed-test">speed test</a> sites.</p><h2 id="what-counts-as-a-client" tabindex="-1">What Counts as a Client <a class="header-anchor" href="#what-counts-as-a-client" aria-label="Permalink to &quot;What Counts as a Client&quot;">​</a></h2><p>Clients are identified by source IP: IPv4 by individual address, IPv6 by its <code>/64</code> subnet. IPv6 addresses within the same <code>/64</code> subnet share one quota.</p><p>When Pavonis runs behind a reverse proxy, the client IP depends on the trusted proxy settings in <a href="./../config/server"><code>server</code></a>.</p><h2 id="traffic-limiting" tabindex="-1">Traffic Limiting <a class="header-anchor" href="#traffic-limiting" aria-label="Permalink to &quot;Traffic Limiting&quot;">​</a></h2><p>Uses a token bucket algorithm to control the traffic rate: the bucket fills at <code>traffic_avg_mibps</code> tokens per second, and transferring 1 MiB of data consumes 1 token. Tokens saved up while idle, up to <code>traffic_burst_mib</code>, allow short bursts above the average rate. <code>traffic_max_mibps</code> caps the peak rate.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>           traffic_avg_mibps (steady refill)</span></span>
<span class="line"><span>                  │</span></span>
<span class="line"><span>                  ▼</span></span>
<span class="line"><span>           ┌─────────────┐</span></span>
<span class="line"><span>           │ ● ● ● ● ●   │  capacity traffic_burst_mib</span></span>
<span class="line"><span>           │ ● ● ● ● ●   │  fills up while idle, allows short bursts</span></span>
<span class="line"><span>           └──────┬──────┘</span></span>
<span class="line"><span>                  │ 1 token per 1 MiB transferred</span></span>
<span class="line"><span>                  ▼</span></span>
<span class="line"><span>       transfer rate ≤ traffic_max_mibps</span></span></code></pre></div><p>When traffic exceeds the limit, the transfer waits for tokens: it slows down rather than being interrupted or rejected.</p><p>Traffic is counted as upload and download combined. The <code>global_traffic_*</code> fields mirror the per-client ones and apply to the combined traffic of all clients, useful for controlling the server&#39;s total bandwidth.</p><h2 id="request-rate-limiting" tabindex="-1">Request Rate Limiting <a class="header-anchor" href="#request-rate-limiting" aria-label="Permalink to &quot;Request Rate Limiting&quot;">​</a></h2><p>Limits the number of requests per client. Per-second, per-minute and per-hour limits can apply simultaneously. A request exceeding any of them is rejected with <code>429 Too Many Requests</code>.</p>`,16)])])}const h=a(n,[["render",r]]);export{u as __pageData,h as default};
